##### ExplodingBoulder
1	public class ExplodingBoulder : Projectile
2	private static GameObject prefab;
3	private CircleCollider2D[] circCols;
4	public bool released;
5	private bool releaseVarsSet;
6	private Vector2 releaseVector;
7	private int baseDamage;
8	public int maxCharge = 20;
9	public int currentCharge;
10	private float chargeProgress;
11	private bool chargeCompleted;
12	private bool targetHit;
13	private int hitStopwatchID;
14	private float hitDelay = 0.062f;
15	private bool hitWall;
16	private Vector2 currentPosition;
17	private bool showSpark;
18	private ThrownCaltrop currentTC;
19	private AttackInfo caltropInfo;
20	private float animSpeed = 1f;
21	private ChaosQuickStopwatch audioStopwatch = new ChaosQuickStopwatch(0.2f);
22	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/Projectiles/ExplodingBoulder.prefab"));
23	private float LerpValue => (float)currentCharge / (float)maxCharge;
24	public override void Awake()
25	base.Awake();
26	circCols = GetComponentsInChildren<CircleCollider2D>();
27	EnableColliders(status: false);
28	Hide();
29	public override void Start()
30	base.Start();
31	baseDamage = calculatedDamage;
32	Attack attack = attackBox;
33	attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
34	Attack attack2 = attackBox;
35	attack2.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Combine(attack2.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
36	public override void Update()
37	if (!targetHit && !audioStopwatch.IsRunning)
38	audioStopwatch.IsRunning = true;
39	SoundManager.PlayWithDistAndSPR("DrillLoop", transform.position, 0.85f);
40	if (!releaseVarsSet)
41	if (!chargeCompleted)
42	chargeProgress = LerpValue;
43	chargeCompleted = chargeProgress >= 1f;
44	animSpeed = Mathf.Lerp(0.1f, 3f, chargeProgress);
45	anim.speed = animSpeed;
46	moveSpeed = Mathf.Lerp(10f, 20f, chargeProgress);
47	if (!projectileSpriteRenderer.enabled)
48	Show();
49	if (!released)
50	return;
51	releaseVarsSet = true;
52	releaseVector = moveVector;
53	EnableColliders();
54	calculatedDamage = baseDamage * currentCharge;
55	base.Update();
56	public override void FixedUpdate()
57	base.FixedUpdate();
58	if (!targetHit)
59	return;
60	switch (ChaosStopwatch.CheckInterval(hitStopwatchID))
61	case StopwatchState.Ready:
62	currentCharge--;
63	attackBox.gameObject.SetActive(value: true);
64	if (hitWall)
65	showSpark = !showSpark;
66	if (showSpark)
67	currentPosition = transform.position;
68	PoolManager.GetPoolItem<HitSparkEmitter>().EmitSingle(HitSparkType.Small, currentPosition, currentPosition + UnityEngine.Random.insideUnitCircle);
69	SoundManager.PlayWithDistAndSPR("PopSnap", transform.position);
70	break;
71	case StopwatchState.Running:
72	attackBox.gameObject.SetActive(value: false);
73	break;
74	case StopwatchState.Done:
75	ResetProjectile();
76	break;
77	public override void ResetProjectile()
78	currentPosition = transform.position;
79	Attack attack = attackBox;
80	attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
81	attackBox.gameObject.SetActive(value: false);
82	LeafEmitter poolItem = PoolManager.GetPoolItem<LeafEmitter>("FallingLeafEmitter");
83	int? particleCount = 4;
84	Vector3? position = currentPosition + Vector2.up;
85	ParticleSystemOverride radiusTwo = ParticleEffectOverrides.RadiusTwo;
86	poolItem.EmitSingle(particleCount, position, radiusTwo);
87	PoolManager.GetPoolItem<ParticleEffect>("ThornEmitter").Emit(30, currentPosition);
88	PoolManager.GetPoolItem<ParticleEffect>("ThornEmitter").Emit(10, currentPosition, ParticleEffectOverrides.Radius0p25);
89	base.ResetProjectile();
90	SoundManager.PlayWithDistAndSPR("ExplosionPop", currentPosition);
91	if (released)
92	if (chargeCompleted)
93	CreateCaltropRing();
94	EarthBurst.CreateBurst(currentPosition, attackBox.GetAtkInfoAtLevel(3), 2.5f).skipParticleEmit = true;
95	else
96	EarthBurst.CreateBurst(currentPosition, attackBox.GetAtkInfoAtLevel(2), 2.5f).skipParticleEmit = true;
97	public void OnTargetHit(Entity givenEnt)
98	if ((hitWall || (!(givenEnt == null) && !(givenEnt is Destructible))) && !targetHit)
99	targetHit = true;
100	moveSpeed = 3f;
101	currentCharge--;
102	hitStopwatchID = ChaosStopwatch.Begin(hitDelay, useInterval: true, hitDelay, currentCharge);
103	flyTime = hitDelay * (float)currentCharge + 1f;
104	RefreshFlightTime();
105	SoundManager.PlayWithDistAndSPR("PopSnap", transform.position);
106	private void CreateCaltropRing()
107	caltropInfo = attackBox.GetAtkInfoAtLevel(4);
108	AttackInfo.SetFloorTargets(caltropInfo.targetNames);
109	currentPosition = transform.position + Vector3.down * 0.9f;
110	if (hitWall)
111	currentPosition -= releaseVector * 1.5f;
112	CreateCaltrop(currentPosition);
113	for (int i = 1; i < 12; i += 2)
114	CreateCaltrop(currentPosition + Globals.GetRotatedCircleVector(12, i, releaseVector) * 1.5f);
115	for (int j = 0; j < 6; j++)
116	CreateCaltrop(currentPosition + Globals.GetRotatedCircleVector(6, j, releaseVector) * 2.75f);
117	private void CreateCaltrop(Vector2 givenPosition)
118	if (Globals.CheckCircle(givenPosition, 0.125f, ChaosCollisions.layerAllWallAndObst))
119	currentTC = Globals.ChaosInst<ThrownCaltrop>(ThrownCaltrop.Prefab, null, currentPosition);
120	currentTC.attack.SetAttackInfo(caltropInfo);
121	currentTC.targetPosition = givenPosition;
122	currentTC.lifeTime = 3.5f;
123	currentTC.layerMask = ChaosCollisions.layerAllWallAndObst;
124	currentTC.useLineCastPosition = true;
125	public void EnableColliders(bool status = true)
126	for (int i = 0; i < circCols.Length; i++)
127	circCols[i].enabled = status;
128	public override void OnProjectileCollision(Collider2D other, Projectile otherProjectile, bool doCalculations = true)
129	if (doCalculations)
130	int num = calculatedDamage - otherProjectile.calculatedDamage;
131	otherProjectile.calculatedDamage -= calculatedDamage;
132	calculatedDamage = num;
133	otherProjectile.OnProjectileCollision(other, this, doCalculations: false);
134	if (calculatedDamage > 10)
135	currentCharge = Mathf.CeilToInt(calculatedDamage / baseDamage);
136	otherProjectile.calculatedDamage = 0;
137	else
138	currentCharge = 0;
139	calculatedDamage = 0;
140	HandleCollision(other);
141	collidedProjectiles.Add(otherProjectile);
142	public override void HandleWallCollision(Collider2D hitCol)
143	if (!hitWall)
144	hitWall = true;
145	updateVelocity = false;
146	moveVector = Vector2.zero;
147	rigidbody2D.velocity = Vector2.zero;
148	attackBox.knockbackMultiplierOverride = -1f;
149	attackBox.atkInfo.knockbackMultiplier = -5f;
150	attackBox.atkInfo.knockbackOverwrite = false;
151	OnTargetHit(null);
152	if (Projectile.globalProjectileWallCollisionEvents != null)
153	Projectile.globalProjectileWallCollisionEvents(this);
154	SoundManager.PlayWithDistAndSPR("PopSnap", transform.position);
