1	public class FireArc : Projectile
2	private static GameObject prefab;
3	[HideInInspector]
4	public Vector2 targetVector;
5	[HideInInspector]
6	public float arcRange = 5f;
7	[HideInInspector]
8	public bool positiveApproach = true;
9	[HideInInspector]
10	public float accuracyOffset = 0.707f;
11	private ChaosQuickStopwatch arcStopwatch = new ChaosQuickStopwatch();
12	private Vector2 initMoveVector;
