	private ChaosQuickStopwatch atkStopwatch = new ChaosQuickStopwatch(0.2f);
	private ParticleSystem fireSys;
	private Animator anim;
	public Transform followTrans;
	public float duration = 3f;
	private int durationStopwatchID;
	private bool destroyQueued;
	public Entity parentEntity;
	private AudioSource audioSource;
	private bool burstOnReset;
	private string burstCategory = string.Empty;
	private string burstID = string.Empty;
	private int burstLevel = 1;
	private float burstScale = 1f;
	private void Awake()
		attack = transform.Find("Attack").GetComponent<Attack>();
		atkCollider = attack.transform.GetComponent<Collider2D>();
		fireSys = transform.Find("FireEmitter").GetComponent<ParticleSystem>();
		anim = transform.GetComponent<Animator>();
	private void Start()
		durationStopwatchID = ChaosStopwatch.Begin(duration);
		destroyQueued = false;
	private void Update()
		if (destroyQueued)
			return;
		if (ChaosStopwatch.Check(durationStopwatchID) || followTrans == null || (parentEntity != null && parentEntity.fsm.currentStateName.Contains("Dead")))
			destroyQueued = true;
			Object.Destroy(gameObject, 1f);
			attack.gameObject.SetActive(value: false);
			fireSys.Stop();
			if (burstOnReset)
				FlameBurst.CreateBurst(transform.position, burstCategory, burstID, burstLevel, burstScale);
		HandleAudio();
	private void FixedUpdate()
		if (followTrans != null)
			transform.position = followTrans.position;
		if (atkFlipped)
			atkFlipped = false;
			atkCollider.enabled = true;
		else if (!atkStopwatch.IsRunning)
			atkStopwatch.IsRunning = true;
			atkFlipped = true;
			atkCollider.enabled = false;
	private void HandleAudio()
		if (destroyQueued)
			if (audioSource != null)
				audioSource.Stop();
		else if (audioSource == null || !audioSource.isPlaying)
	public void SetBurstVars(string givenCategory, string givenID, int givenLevel, float givenScale)
		burstOnReset = true;
		burstCategory = givenCategory;
		burstID = givenID;
		burstLevel = givenLevel;
		burstScale = givenScale;
	public void Stop()
		ChaosStopwatch.Stop(durationStopwatchID);
