public Vector3 playerPos = Vector3.zero;
private float tempColorVal;
private MeteorRain curMeteorRain;
private void Awake()
if (initLocArr == null)
initLocArr = new Vector2[5];
for (int i = 0; i < 5; i++)
ref Vector2 reference = ref initLocArr[i];
reference = Globals.GetCirclePositionVector(5, i) * 1.5f;
dropLocArr = new Vector2[dropLocCount];
for (int j = 0; j < dropIndex; j++)
ref Vector2 reference2 = ref dropLocArr[j];
reference2 = Globals.GetCirclePositionVector(dropIndex, j) * 1.5f;
ref Vector2 reference3 = ref dropLocArr[dropIndex];
reference3 = Vector2.zero;
private void Start()
currentPosition = transform.position;
randSeed = Random.Range(0, initLocCount);
circleSprite.enabled = useCastCircle;
private void FixedUpdate()
HandleCircleSprite();
if (destroyQueued || !ChaosStopwatch.Check(rainStopwatchID))
return;
if (initDropCount > 0)
initDropCount--;
CreateMeteorRain(currentPosition + initLocArr[(initDropCount + randSeed) % initLocCount]);
rainStopwatchID = ChaosStopwatch.Begin(0.05f);
return;
CreateMeteorRain(currentPosition + dropLocArr[dropIndex]);
dropIndex = (dropIndex + Random.Range(1, 5)) % dropLocCount;
rainCount--;
if (rainCount <= 0)
destroyQueued = true;
Object.Destroy(gameObject, 0.5f);
colorFlip = false;
spriteStopwatch.IsRunning = true;
else
rainStopwatchID = ChaosStopwatch.Begin((!(Random.value < 0.3f)) ? Random.Range(0.15f, 0.25f) : 0.0625f);
private void CreateMeteorRain(Vector2 givenPosition)
curMeteorRain = Globals.ChaosInst<MeteorRain>(MeteorRain.Prefab, transform.parent, givenPosition);
curMeteorRain.SetSkillInfo(atkInfo, skillAnim);
curMeteorRain.useReducedEffects = useReducedEffects;
if (playerPos != Vector3.zero)
tempColorVal = Globals.LerpWithRange(-5f, 5f, playerPos.y - transform.position.y, 0.6f, 1.25f);
curMeteorRain.sprite.color = new Color(tempColorVal, tempColorVal, 1f);
private void HandleCircleSprite()
if (useCastCircle && circleSprite != null)
colorLerpValue = spriteStopwatch.TimePercentage;
if (colorLerpValue >= 1f)
colorFlip = !colorFlip;
spriteStopwatch.IsRunning = true;
circleSprite.color = ((!colorFlip) ? Color.Lerp(fullColor, emptyColor, spriteStopwatch.TimePercentage) : Color.Lerp(emptyColor, fullColor, spriteStopwatch.TimePercentage));
